use crabxl_core::{Cell, CellAddress, CellValue, EditLimits, StyleId, Worksheet};
fn main() -> Result<(), Box<dyn std::error::Error>> {
    let mode = std::env::args().nth(1).unwrap_or_else(|| "ascending".to_owned());
    let reverse = mode == "reverse";
    let shift = mode == "shift";
    let budget = if shift { 384 * 1024 * 1024 } else { 64 * 1024 * 1024 };
    let mut sheet = Worksheet::new("Sheet", EditLimits { max_bytes: budget, ..Default::default() })?;
    let mut failure = None;
    for offset in 0..1_000_000u32 {
        let index = if reverse { 999_999 - offset } else { offset };
        if let Err(error) = sheet.set(Cell {
            address: CellAddress::new(index / 10, index % 10)?,
            value: CellValue::Integer(index.into()),
            style: StyleId::new(0),
        }) {
            assert_eq!(error.kind(), crabxl_core::ErrorKind::MemoryBudgetExceeded);
            failure = Some(error.kind());
            break;
        }
    }
    let mut shifted = false;
    if shift && failure.is_none() {
        match sheet.insert_rows(crabxl_core::RowIndex::new(0)?, 1) {
            Ok(()) => shifted = true,
            Err(error) => assert_eq!(error.kind(), crabxl_core::ErrorKind::MemoryBudgetExceeded),
        }
    }
    let mut checksum = 0i64;
    for cell in sheet.cells() {
        let index = (cell.address.row.get() - u32::from(shifted)) * 10 + cell.address.column.get();
        let CellValue::Integer(value) = cell.value else { panic!("Expected integer"); };
        assert_eq!(value, i64::from(index));
        checksum += value;
    }
    assert!(sheet.charged_bytes() <= budget);
    if failure.is_none() {
        assert_eq!(sheet.len(), 1_000_000);
        assert_eq!(checksum, 499_999_500_000);
    }
    println!("{{\"mode\":\"{}\",\"cells\":{},\"checksum\":{},\"charged_bytes\":{},\"budget_bytes\":{},\"complete\":{},\"shifted\":{}}}",
        mode, sheet.len(), checksum, sheet.charged_bytes(), budget, failure.is_none(), shifted);
    Ok(())
}
